CREATE SCHEMA IF NOT EXISTS regulatory;
CREATE TABLE regulatory.regulatory_sources (source_id uuid PRIMARY KEY, issuer text NOT NULL, canonical_uri text NOT NULL, title text, language text NOT NULL, published_at timestamptz, retrieved_at timestamptz NOT NULL, checksum_algorithm text NOT NULL CHECK (checksum_algorithm = 'sha256'), checksum_hex text NOT NULL CHECK (checksum_hex ~ '^[0-9a-f]{64}$'), object_ref text, verification_state text NOT NULL CHECK (verification_state IN ('UNVERIFIED','VERIFIED','REJECTED')), authoritative boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (issuer, checksum_algorithm, checksum_hex));
CREATE TABLE regulatory.regulations (regulation_id uuid PRIMARY KEY, jurisdiction text NOT NULL, authority text NOT NULL, code text NOT NULL, title text NOT NULL, UNIQUE (jurisdiction, code));
CREATE TABLE regulatory.regulation_versions (regulation_version_id uuid PRIMARY KEY, regulation_id uuid NOT NULL REFERENCES regulatory.regulations, revision integer NOT NULL CHECK (revision > 0), effective_from date NOT NULL, effective_to date, recorded_at timestamptz NOT NULL DEFAULT now(), state text NOT NULL CHECK (state IN ('DRAFT','REVIEWED','PUBLISHED','SUPERSEDED','RETIRED')), supersedes_id uuid REFERENCES regulatory.regulation_versions, UNIQUE (regulation_id, revision), CHECK (effective_to IS NULL OR effective_from < effective_to));
CREATE TABLE regulatory.provisions (provision_id uuid PRIMARY KEY, regulation_id uuid NOT NULL REFERENCES regulatory.regulations, code text NOT NULL, UNIQUE (regulation_id, code));
CREATE TABLE regulatory.source_citations (citation_id uuid PRIMARY KEY, source_id uuid NOT NULL REFERENCES regulatory.regulatory_sources, source_digest text NOT NULL CHECK (source_digest ~ '^[0-9a-f]{64}$'), locator text NOT NULL, page integer CHECK (page IS NULL OR page > 0), paragraph text);
CREATE TABLE regulatory.provision_versions (provision_version_id uuid PRIMARY KEY, provision_id uuid NOT NULL REFERENCES regulatory.provisions, regulation_version_id uuid NOT NULL REFERENCES regulatory.regulation_versions, language text NOT NULL, text_content text NOT NULL, locator text NOT NULL, page integer CHECK (page IS NULL OR page > 0), paragraph text, effective_from date NOT NULL, effective_to date, citation_id uuid NOT NULL REFERENCES regulatory.source_citations, UNIQUE (provision_id, regulation_version_id, language), CHECK (effective_to IS NULL OR effective_from < effective_to));
CREATE TABLE regulatory.requirements (requirement_id uuid PRIMARY KEY, requirement_code text NOT NULL UNIQUE, classification text NOT NULL CHECK (classification IN ('LEGAL_REQUIREMENT','IMPLEMENTATION_CONTROL','GOOD_PRACTICE')), family text);
CREATE TABLE regulatory.requirement_versions (requirement_version_id uuid PRIMARY KEY, requirement_id uuid NOT NULL REFERENCES regulatory.requirements, revision integer NOT NULL CHECK (revision > 0), atomic_wording text NOT NULL, interpretation_note text, review_state text NOT NULL CHECK (review_state IN ('DRAFT','REVIEWED','PUBLISHED','SUPERSEDED','RETIRED')), effective_from date NOT NULL, effective_to date, provision_version_id uuid REFERENCES regulatory.provision_versions, citation_id uuid REFERENCES regulatory.source_citations, reviewer_ref text, UNIQUE (requirement_id, revision), CHECK (effective_to IS NULL OR effective_from < effective_to), CHECK (review_state = 'DRAFT' OR reviewer_ref IS NOT NULL));
CREATE TABLE regulatory.requirement_aliases (alias_id uuid PRIMARY KEY, requirement_id uuid NOT NULL REFERENCES regulatory.requirements, namespace text NOT NULL, alias text NOT NULL, UNIQUE (namespace, alias));
CREATE TABLE regulatory.applicability_rules (applicability_rule_id uuid PRIMARY KEY, code text NOT NULL, revision integer NOT NULL CHECK (revision > 0), predicate jsonb NOT NULL, required_facts jsonb NOT NULL, unknown_behavior text NOT NULL CHECK (unknown_behavior = 'UNKNOWN'), UNIQUE (code, revision));
CREATE TABLE regulatory.publication_manifests (manifest_id uuid PRIMARY KEY, digest text NOT NULL UNIQUE CHECK (digest ~ '^[0-9a-f]{64}$'), source_refs jsonb NOT NULL, version_set jsonb NOT NULL, signature_ref text, reviewer_ref text, state text NOT NULL CHECK (state IN ('DRAFT','REVIEWED','PUBLISHED','REVOKED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION regulatory.reject_published_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (TG_TABLE_NAME = 'requirement_versions' AND OLD.review_state = 'PUBLISHED') OR (TG_TABLE_NAME = 'regulation_versions' AND OLD.state = 'PUBLISHED') THEN RAISE EXCEPTION 'published regulatory versions are immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER requirement_versions_immutable BEFORE UPDATE OR DELETE ON regulatory.requirement_versions FOR EACH ROW EXECUTE FUNCTION regulatory.reject_published_mutation();
CREATE TRIGGER regulation_versions_immutable BEFORE UPDATE OR DELETE ON regulatory.regulation_versions FOR EACH ROW EXECUTE FUNCTION regulatory.reject_published_mutation();
